process.on('SIGTERM', () => {
  // We must exit with status 0 within 3 seconds
  const timer = setTimeout(() => {
    process.exit(0);
  }, 2500);

  cleanup().then(() => {
    clearTimeout(timer);
  });
});

process.on('SIGINT', () => {
  cleanup();
});

async function main() {
